import java.io.*;
import java.util.*;


public class DVDElevator2012 {
    public static final long MILLISECONDS_TO_MICROSECONDS = 1000;
    public static final long MICROSECONDS_PER_BATCH = 10 * MILLISECONDS_TO_MICROSECONDS;
    
    public static class ReadRequest implements Comparable<ReadRequest> {
        public long mSectorStart;
        public long mSectorEnd;
        
        public int compareTo(ReadRequest o) {
            long diff = this.mSectorStart - o.mSectorStart;
            if (diff < 0) {
                return -1;
            }
            else if (diff > 0) {
                return 1;
            }
            else {
                return 1;
            }
        }
    }
    
    public static void main(String args[]) throws IOException
    {
    	Scanner kb = new Scanner(new File("dvdelevator2012.dat"));
    	
        long batchEndMicrosecond = 0;
        long laserPos = 0;
        
        PriorityQueue<ReadRequest> batch = new PriorityQueue<ReadRequest>();
        
        while (kb.hasNextLine()) {
            String strLine = kb.nextLine();
            
            String[] strArr = strLine.split(" ");
            
            long startTimeMicroseconds = Long.parseLong(strArr[0]);
            long sectorStart = Long.parseLong(strArr[1]);
            long sectorEnd = Long.parseLong(strArr[2]);
            
            if (batchEndMicrosecond !=0 && startTimeMicroseconds > batchEndMicrosecond) {
            	while (!batch.isEmpty()) {
            		ReadRequest req = batch.remove();
            		System.out.printf("Time %d: %d to %d\n", batchEndMicrosecond, req.mSectorStart, req.mSectorEnd);
            		laserPos = req.mSectorEnd + 1;
            	}
            	
            	batchEndMicrosecond = 0;
            }
            
            if (sectorStart >= laserPos) {
            	System.out.printf("Time %d: %d to %d\n", startTimeMicroseconds, sectorStart, sectorEnd);
            	laserPos = sectorEnd + 1;
            }
            else {
            	if (batchEndMicrosecond == 0) {
            		batchEndMicrosecond = startTimeMicroseconds + MICROSECONDS_PER_BATCH;
            	}
            	
            	ReadRequest req = new ReadRequest();
            	req.mSectorStart = sectorStart;
            	req.mSectorEnd = sectorEnd;
            	batch.add(req);
            }
        }
        
        if (batchEndMicrosecond !=0) {
        	while (!batch.isEmpty()) {
        		ReadRequest req = batch.remove();
        		System.out.printf("Time %d: %d to %d\n", batchEndMicrosecond, req.mSectorStart, req.mSectorEnd);
        		laserPos = req.mSectorEnd + 1;
        	}
        }
    }
}

import java.io.*;
import java.util.*;

public class Escape {
    
    public static final char kCellEmpty     = '.';
    public static final char kCellObstacle  = '#';
    public static final char kCellYou       = 'Y';
    public static final char kCellBear      = 'B';
    public static final char kCellEscape    = 'E';
    public static final char kCellVisited   = 'o';
    
    public static char[][] grid = null;
    public static int gridRows = 0;
    public static int gridCols = 0;
    
    public static int numTimesEscaped = 0;
    public static int numTimesEaten = 0;
    
    public static char getGridValSafe(int r, int c) {
        if (r < 0 || r >= gridRows) {
            return kCellObstacle;
        }
                
        if (c < 0 || c >= gridCols) {
            return kCellObstacle;
        }
        
        return grid[r][c];
    }
    
    public static void recurse(int youCurR, 
                               int youCurC, 
                               int youNextR, 
                               int youNextC,
                               int bearCurR,
                               int bearCurC,
                               char lastBearCell) {

        char chDst = getGridValSafe(youNextR, youNextC);
        if (kCellEscape == chDst) {
            ++numTimesEscaped;
            return;
        }
        else if (kCellEmpty != chDst) {
            return;
        }
        
        // Perform the move
        grid[youCurR][youCurC] = kCellVisited;
        grid[youNextR][youNextC] = kCellYou;
        
        // Bear move time
        int bearNextR = bearCurR;
        int bearNextC = bearCurC;
        
        char ul = getGridValSafe(bearCurR - 1, bearCurC - 1);
        char cl = getGridValSafe(bearCurR + 0, bearCurC - 1);
        char dl = getGridValSafe(bearCurR + 1, bearCurC - 1);
        char uc = getGridValSafe(bearCurR - 1, bearCurC + 0);
        char dc = getGridValSafe(bearCurR + 1, bearCurC + 0);
        char ur = getGridValSafe(bearCurR - 1, bearCurC + 1);
        char cr = getGridValSafe(bearCurR + 0, bearCurC + 1);
        char dr = getGridValSafe(bearCurR + 1, bearCurC + 1);
        
        // Adjacent You means dinner!
        if (    kCellYou == ul || kCellYou == cl || kCellYou == dl || kCellYou == uc
             || kCellYou == dc || kCellYou == ur || kCellYou == cr || kCellYou == dr) {
            ++numTimesEaten;
            
            // Set back values
            grid[youCurR][youCurC] = kCellYou;
            grid[youNextR][youNextC] = chDst;
            
            return;
        }
        
        int diffR = youNextR - bearCurR;
        if (diffR < 0) {
            --bearNextR;
        }
        else if (diffR > 0) {
            ++bearNextR;
        }
        
        int diffC = youNextC - bearCurC;
        if (diffC < 0) {
            --bearNextC;
        }
        else if (diffC > 0) {
            ++bearNextC;
        }
        
        char chBearDst = getGridValSafe(bearNextR, bearNextC);
        boolean bBearMoved = false;
        if (kCellObstacle != chBearDst) {
            grid[bearCurR][bearCurC] = lastBearCell;
            grid[bearNextR][bearNextC] = kCellBear;
            bBearMoved = true;
        }
        else {
            bearNextR = bearCurR;
            bearNextC = bearCurC;
            chBearDst = lastBearCell;
        }
        
        // Recurse!
        recurse(youNextR, youNextC, youNextR - 1, youNextC - 1, bearNextR, bearNextC, chBearDst);
        recurse(youNextR, youNextC, youNextR + 0, youNextC - 1, bearNextR, bearNextC, chBearDst);
        recurse(youNextR, youNextC, youNextR + 1, youNextC - 1, bearNextR, bearNextC, chBearDst);
        
        recurse(youNextR, youNextC, youNextR - 1, youNextC + 0, bearNextR, bearNextC, chBearDst);
        recurse(youNextR, youNextC, youNextR + 1, youNextC + 0, bearNextR, bearNextC, chBearDst);
        
        recurse(youNextR, youNextC, youNextR - 1, youNextC + 1, bearNextR, bearNextC, chBearDst);
        recurse(youNextR, youNextC, youNextR + 0, youNextC + 1, bearNextR, bearNextC, chBearDst);
        recurse(youNextR, youNextC, youNextR + 1, youNextC + 1, bearNextR, bearNextC, chBearDst);
        
        // Set back the values
        if (bBearMoved) {
            grid[bearCurR][bearCurC] = kCellBear;
            grid[bearNextR][bearNextC] = chBearDst;
        }
        
        grid[youCurR][youCurC] = kCellYou;
        grid[youNextR][youNextC] = chDst;
    }
    
    public static void main(String args[]) throws IOException
    {
        // Parse each line in the file
        Scanner kb = new Scanner(new File("escape.dat"));
        
        int numGrids = Integer.parseInt(kb.nextLine().trim());
        for (int g = 0; g < numGrids; ++g) {
            String strLine = kb.nextLine().trim();
            String[] strArr = strLine.split(" ");
            
            gridRows = Integer.parseInt(strArr[0]);
            gridCols = Integer.parseInt(strArr[1]);
            numTimesEscaped = 0;
            numTimesEaten = 0;
            
            grid = new char[gridRows][gridCols];
            
            int bearR = 0;
            int bearC = 0;
            int youR = 0;
            int youC = 0;
            
            for (int r = 0; r < gridRows; ++r) {
                strLine = kb.nextLine().trim();
                
                for (int c = 0; c < gridCols; ++c) {
                    char ch = strLine.charAt(c);
                    if (kCellYou == ch) {
                        youR = r;
                        youC = c;
                    }
                    else if (kCellBear == ch) {
                        bearR = r;
                        bearC = c;
                    }
                    
                    grid[r][c] = ch;
                }
            }
            
            recurse(youR, youC, youR - 1, youC - 1, bearR, bearC, kCellEmpty);
            recurse(youR, youC, youR + 0, youC - 1, bearR, bearC, kCellEmpty);
            recurse(youR, youC, youR + 1, youC - 1, bearR, bearC, kCellEmpty);
            
            recurse(youR, youC, youR - 1, youC + 0, bearR, bearC, kCellEmpty);
            recurse(youR, youC, youR + 1, youC + 0, bearR, bearC, kCellEmpty);
            
            recurse(youR, youC, youR - 1, youC + 1, bearR, bearC, kCellEmpty);
            recurse(youR, youC, youR + 0, youC + 1, bearR, bearC, kCellEmpty);
            recurse(youR, youC, youR + 1, youC + 1, bearR, bearC, kCellEmpty);
            
            System.out.printf("%d%%\n", numTimesEscaped * 100 / (numTimesEscaped + numTimesEaten));
        }
    }    
}

import java.io.*;
import java.util.*;

public class Fences
{
	public static class HomeData {
		public char home;
		public int fence;
	}
	
	public static char charAtSafe(int x, int y) {
		if (x < 0 || x > 7)
			return '*';
		
		if (y < 0 || y > 15)
			return '*';
		
		return grid[x][y];
	}
	
	public static int fenceAmount(char ch, int x, int y) {
		int amount = charAtSafe(x, y - 1) != ch ? 660 : 0;
		amount += charAtSafe(x, y + 1) != ch ? 660 : 0;
		amount += charAtSafe(x - 1, y) != ch ? 330 : 0;
		amount += charAtSafe(x + 1, y) != ch ? 330 : 0;
		return amount;
	}
	
	public static HomeData[] homeData = null;
	public static char[][] grid = null;
	
	public static void main(String args[]) throws IOException
    {
		Scanner kb = new Scanner(new File("fences.dat"));
		int numSurveys = Integer.parseInt(kb.nextLine().trim());
		
		for (int s = 0; s < numSurveys; ++s) {
			String[] homes = kb.nextLine().trim().split(" ");
			homeData = new HomeData[homes.length];
			for (int h = 0; h < homes.length; ++h) {
				homeData[h] = new HomeData();
				homeData[h].home = homes[h].charAt(0);
			}
			
			for (int h1 = 0; h1 < homes.length; ++h1) {
				for (int h2 = 0; h2 < homes.length; ++h2) {
					if (homeData[h1].home < homeData[h2].home){
						HomeData tmp = homeData[h1];
						homeData[h1] = homeData[h2];
						homeData[h2] = tmp;
					}
				}
			}
			
			grid = new char[8][16];
			for (int x = 0; x < 8; ++x) {
				String line = kb.nextLine().trim();
				for (int y = 0; y < 16; ++y) {
					grid[x][y] = line.charAt(y);
				}
			}
			
			for (int x = 0; x < 8; ++x) {
				for (int y = 0; y < 16; ++y) {
					char ch = grid[x][y];
					if (ch != '*') {
						for (int h = 0; h < homeData.length; ++h) {
							if (homeData[h].home == ch) {
								homeData[h].fence += fenceAmount(ch, x, y);
								break;
							}
						}
					}
				}
			}
			
			System.out.printf("SURVEY %d\n", s + 1);
			for (int h = 0; h < homeData.length; ++h) {
				System.out.printf("%c %d\n", homeData[h].home, homeData[h].fence);
			}
		}
    }
}

